WRAPPERS = {"sudo","timeout","nice","nohup","env","command","xargs","time","stdbuf"}

def heads(cmd):
    """Yield (cmd, subcmd) pairs for each segment of a compound command."""
    # split on pipes, &&, ||, ;, newlines
    for seg in re.split(r'\|\||&&|[|;\n]', cmd):
        seg = seg.strip()
        if not seg:
            continue
        # strip $( ) and backticks content markers crudely
        toks = re.findall(r'[^\s]+', seg)
        i = 0
        # strip env-var assignments and wrappers
        while i < len(toks) and (re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', toks[i]) or toks[i] in WRAPPERS):
            if toks[i] in WRAPPERS and toks[i] != "env":
                i += 1
                # skip numeric arg of timeout
                if i < len(toks) and re.match(r'^[0-9]+[smh]?$', toks[i]):
                    i += 1
                continue
            i += 1
        if i >= len(toks):
            continue
        c = toks[i].lstrip('(').lstrip('$').lstrip('(')
        c = os.path.basename(c)
        if not re.match(r'^[A-Za-z0-9_.\-]+$', c):
            continue
        sub = ""
        for t in toks[i+1:]:
            if not t.startswith('-') and re.match(r'^[A-Za-z0-9_:.\-]+$', t):
                sub = t
                break
        yield (c, sub)

